const eventPageAfter = `-- name: EventPageAfter :many
SELECT seq, session_id, kind, at, payload, write_id, answered FROM events WHERE seq > ? ORDER BY seq LIMIT ?
`

type EventPageAfterParams struct {
	Seq   int64
	Limit int64
}

func (q *Queries) EventPageAfter(ctx context.Context, arg EventPageAfterParams) ([]Event, error) {
	rows, err := q.db.QueryContext(ctx, eventPageAfter, arg.Seq, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Event
	for rows.Next() {
		var i Event
		if err := rows.Scan(
			&i.Seq,
			&i.SessionID,
			&i.Kind,
			&i.At,
			&i.Payload,
			&i.WriteID,
			&i.Answered,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

